@startuml

class Animal {
  + Identifier : long
  + Name : string
  + Breed : string
}

class Owner {
  + Identifier : long
  + Name : string
  + Address : string
  + PhoneNumber : string
}

class Breed {
  + Name : string
}

class Physician {
  + Identifier : long
  + Name : string
  + Address : string
  + PhoneNumber : string
}

class Appointment {
  + StartDateTime : datetime
}

class Condition {
  + CommonName : string
  + ScientificName : string
}

Owner "0..1" -- "0..*" Animal : owns
Animal "0..*" -- "1" Breed : is of
Physician "1" -- "0..*" Appointment : is responsible for
Animal "1" -- "0..*" Appointment : is attended
Owner "1" -- "0..*" Appointment : attends
Breed "1" -- "0..*" Condition : has common
Condition "0..*" -- "0..*" Breed : is common for

@enduml

